package me.pikanote.companion;
import android.content.Context;import org.json.*;import java.io.*;import java.nio.file.Files;import java.security.MessageDigest;import java.util.*;import java.util.zip.*;
final class PhoneBackupChecks {
 static void check(boolean ok,String message)throws Exception{if(!ok)throw new Exception(message);}
 static void run(Context context)throws Exception{
  Store store=new Store(context);store.state.put("pending",new JSONArray());JSONObject known=new JSONObject();store.state.put("files",known);Map<String,byte[]> content=new LinkedHashMap<>();content.put("index.csv","note,title\n1,Backup test\n".getBytes("UTF-8"));content.put(".ask-history.json","{\"history\":[]}".getBytes("UTF-8"));content.put("note_001.wav",new byte[1024]);for(Map.Entry<String,byte[]> file:content.entrySet()){Files.write(store.safeFile(file.getKey()).toPath(),file.getValue());known.put(file.getKey(),BleTransport.hex(MessageDigest.getInstance("SHA-256").digest(file.getValue())));}store.state.put("settingsSecrets",new JSONObject().put("test","PRIVATE")).put("appPin","1234");JSONArray dialogue=new JSONArray().put(new JSONObject().put("id","backup-dialogue").put("question","Remember my phrase").put("answer","Remembered").put("createdUtc","2026-11-01T10:00:00Z").put("status","done"));store.state.put("askTurns",dialogue).put("askHiddenBefore","2026-10-01T00:00:00Z");ByteArrayOutputStream bytes=new ByteArrayOutputStream();OutputStream unlocked=new FilterOutputStream(bytes){public void write(byte[] data,int at,int count)throws IOException{if(Thread.holdsLock(store))throw new IOException("Backup holds Store lock while writing");out.write(data,at,count);}public void write(int value)throws IOException{if(Thread.holdsLock(store))throw new IOException("Backup holds Store lock while writing");out.write(value);}};Files.write(new File(context.getFilesDir(),"ask-page.html").toPath(),"<article class='turn'><div class='bubble question'>Legacy question</div><div class='bubble answer'>Legacy answer</div><time>2026-11-01 12:00:00</time></article>".getBytes("UTF-8"));PhoneBackup.write(store,unlocked);dialogue=new JSONArray(store.state.getJSONArray("askTurns").toString());check(dialogue.length()==2,"Cached legacy Ask omitted from backup");Set<String> entries=new HashSet<>();try(ZipInputStream zip=new ZipInputStream(new ByteArrayInputStream(bytes.toByteArray()))){ZipEntry entry;while((entry=zip.getNextEntry())!=null){entries.add(entry.getName());if(entry.getName().equals("pika-phone.json")){ByteArrayOutputStream data=new ByteArrayOutputStream();PhoneBackup.copyBounded(zip,data,4*1024*1024);JSONObject state=new JSONObject(data.toString("UTF-8")).getJSONObject("state");check(!state.has("appPin")&&!state.has("settingsSecrets"),"Backup leaked credentials");}}}check(entries.contains("notes/.ask-history.json")&&entries.contains("notes/note_001.wav"),"Backup omits history or audio");PhoneBackup.restore(store,new ByteArrayInputStream(bytes.toByteArray()));check(store.safeFile("note_001.wav").length()==1024&&store.restoredPending(),"Backup restore failed");check(store.state.getJSONArray("askTurns").toString().equals(dialogue.toString()),"Ask dialogue lost during restore");check(store.state.getString("askHiddenBefore").equals("2026-10-01T00:00:00Z"),"Ask renewal boundary lost");Files.write(store.safeFile("index.csv").toPath(),new byte[]{99});boolean changed=false;try{PhoneBackup.write(store,new ByteArrayOutputStream());}catch(IOException expected){changed=true;}check(changed,"Changed mirror not rejected");store.safeFile("note_001.wav").delete();boolean missing=false;try{PhoneBackup.write(store,new ByteArrayOutputStream());}catch(IOException expected){missing=true;}check(missing,"Missing mirror silently omitted");
 }
}
